import os

for root, dirs, files in os.walk('.'):
    # skip hidden skill dirs for brevity but show them too
    depth = root.count(os.sep)
    if depth > 4:
        continue
    for f in files:
        p = os.path.join(root, f)
        if p.startswith('./.codex'):
            continue
        print(os.path.abspath(p))

import os

try:
    from defusedxml import minidom
except Exception:
    from xml.dom import minidom

HERE = os.path.dirname(os.path.abspath(__file__))
XML = os.path.join(HERE, 'unpacked_quarterly', 'word', 'document.xml')

# CT_RPr child order so <w:u> is inserted at a schema-valid position
RPR_ORDER = ['w:rStyle', 'w:rFonts', 'w:b', 'w:bCs', 'w:i', 'w:iCs', 'w:caps',
             'w:smallCaps', 'w:strike', 'w:dstrike', 'w:outline', 'w:shadow',
             'w:emboss', 'w:imprint', 'w:noProof', 'w:snapToGrid', 'w:vanish',
             'w:webHidden', 'w:color', 'w:spacing', 'w:w', 'w:kern', 'w:position',
             'w:sz', 'w:szCs', 'w:highlight', 'w:u', 'w:effect', 'w:bdr', 'w:shd',
             'w:fitText', 'w:vertAlign', 'w:rtl', 'w:cs', 'w:em', 'w:lang',
             'w:eastAsianLayout', 'w:specVanish', 'w:oMath']


def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue or '')
    return ''.join(parts).strip()


def is_headline(p):
    text = para_text(p)
    if not text:
        return False
    if not any(c.isalpha() for c in text):
        return False
    if any(c.islower() for c in text):
        return False
    return True


def add_underline(rPr):
    for u in rPr.getElementsByTagName('w:u'):
        rPr.removeChild(u)
    u = rPr.ownerDocument.createElement('w:u')
    u.setAttribute('w:val', 'single')
    u_idx = RPR_ORDER.index('w:u')
    anchor = None
    for child in rPr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName in RPR_ORDER:
            if RPR_ORDER.index(child.tagName) > u_idx:
                anchor = child
                break
    if anchor is not None:
        rPr.insertBefore(u, anchor)
    else:
        rPr.appendChild(u)


doc = minidom.parse(XML)
headlines = []
for p in doc.getElementsByTagName('w:p'):
    if not is_headline(p):
        continue
    runs = p.getElementsByTagName('w:r')
    if not runs:
        continue
    for r in runs:
        rPrs = r.getElementsByTagName('w:rPr')
        if rPrs:
            add_underline(rPrs[0])
        else:
            rPr = r.ownerDocument.createElement('w:rPr')
            r.insertBefore(rPr, r.firstChild)
            u = r.ownerDocument.createElement('w:u')
            u.setAttribute('w:val', 'single')
            rPr.appendChild(u)
    headlines.append(para_text(p))

content = doc.documentElement.toxml()
data = ('<?xml version="1.0" encoding="ascii"?>\n' + content).encode('ascii', 'xmlcharrefreplace')
with open(XML, 'wb') as f:
    f.write(data)

print('Underlined headlines: %d' % len(headlines))
for h in headlines:
    print(' -', h)

