import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(ROOT, ".codex", "skills", "docx"))

from scripts.document import Document  # noqa: E402

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

doc = Document(os.path.join(ROOT, "unpacked_quarterly"))
editor = doc["word/document.xml"]
dom = editor.dom


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue)
    return "".join(parts)


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    if s[0] in "\u2022\u25aa\u25cf*":
        return False
    letters = [c for c in s if c.isalpha()]
    if len(letters) < 3:
        return False
    return all(c.isupper() for c in letters)


headlines = []
for p in dom.getElementsByTagName("w:p"):
    text = para_text(p)
    if not is_headline(text):
        continue
    headlines.append(text.strip())
    for r in p.getElementsByTagName("w:r"):
        has_text = any(t.firstChild is not None and t.firstChild.nodeValue for t in r.getElementsByTagName("w:t"))
        if not has_text:
            continue
        rpr = None
        for child in r.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
                rpr = child
                break
        if rpr is None:
            rpr = dom.createElementNS(W_NS, "w:rPr")
            r.insertBefore(rpr, r.firstChild)
        u = None
        for child in rpr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:u":
                u = child
                break
        if u is None:
            u = dom.createElementNS(W_NS, "w:u")
            rpr.appendChild(u)
        u.setAttributeNS(W_NS, "w:val", "single")

print("Headlines underlined: %d" % len(headlines))
for h in headlines:
    print("- " + h)

doc.save()

