    for r in p.getElementsByTagName("w:r"):
        has_text = any(
            t.firstChild is not None and t.firstChild.nodeValue
            for t in r.getElementsByTagName("w:t")
        )
        if not has_text:
            continue
        rpr = get_child(r, "w:rPr")
        if rpr is None:
            rpr = dom.createElementNS(W_NS, "w:rPr")
            r.insertBefore(rpr, r.firstChild)
        u = get_child(rpr, "w:u")
        if u is None:
            u = dom.createElementNS(W_NS, "w:u")
            rpr.appendChild(u)
        u.setAttributeNS(W_NS, "w:val", "single")

print("Headlines underlined: %d" % len(headlines))
for h in headlines:
    print("- " + h)

with open(xml_path, "w", encoding="utf-8") as f:
    dom.writexml(f, encoding="utf-8")
